DO $$ DECLARE definition text; BEGIN SELECT pg_get_functiondef('public.sante_valider_tva(uuid)'::regprocedure) INTO definition; definition:=replace(definition,'JOIN public.tva_parametrage b ON b.entreprise_id=a.entreprise_id AND b.compte_tva_deductible=a.compte_tva_collectee','JOIN public.tva_parametrage other_param ON other_param.entreprise_id=a.entreprise_id AND other_param.compte_tva_deductible=a.compte_tva_collectee'); definition:=replace(definition,'AND a.actif AND b.actif','AND a.actif AND other_param.actif'); EXECUTE definition; END $$;